SELECT run_id, COUNT(*) AS "Compensações"
FROM saga_auditoria WHERE run_id = ANY(CASE WHEN '${grupo}' = 'manual' THEN ARRAY[${run_ids:sqlstring}]::text[] ELSE string_to_array('${grupo}', ';') END) AND acao = 'COMPENSACAO'
GROUP BY run_id ORDER BY run_id;

SELECT run_id, COUNT(*) AS "Retries"
FROM saga_auditoria WHERE run_id = ANY(CASE WHEN '${grupo}' = 'manual' THEN ARRAY[${run_ids:sqlstring}]::text[] ELSE string_to_array('${grupo}', ';') END) AND acao = 'RETRY'
GROUP BY run_id ORDER BY run_id;

SELECT run_id, COUNT(*) AS "Eventos registrados"
FROM saga_auditoria WHERE run_id = ANY(CASE WHEN '${grupo}' = 'manual' THEN ARRAY[${run_ids:sqlstring}]::text[] ELSE string_to_array('${grupo}', ';') END)
GROUP BY run_id ORDER BY run_id;

SELECT run_id, servico, COUNT(*)::int AS eventos
FROM saga_auditoria WHERE run_id = ANY(CASE WHEN '${grupo}' = 'manual' THEN ARRAY[${run_ids:sqlstring}]::text[] ELSE string_to_array('${grupo}', ';') END)
GROUP BY run_id, servico ORDER BY run_id, servico;
